// async-retry | retry / async-await | large / p3
// Defensive variant with descriptive identifiers.

async function withRetry_safe<T>(
  task: () => Promise<T>,
  attempts: number,
  delayMs: number,
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
      if (attempt < attempts) {
        await new Promise<void>((resolve) => setTimeout(resolve, delayMs));
      }
    }
  }
  throw new Error(`task failed after ${attempts} attempts: ${String(lastError)}`);
}

async function main(): Promise<void> {
  const value = await withRetry_safe(async () => 20, 2, 11);
  console.log(`resolved=${value} tag=gamma`);
}

